css:
/* As coordenadas chegam do JS em custom properties; aqui só se pinta.
   Nada disso existe sem a classe .fx-on na raiz, que o JS só adiciona em
   ponteiro fino e sem prefers-reduced-motion. */

/* 1. SPOTLIGHT NO CURSOR
   Fica atrás do conteúdo (z-index 1, mesma faixa do blueprint) — é um brilho
   no fundo, não um véu por cima do texto. */
.fx-spotlight {
  position: fixed; inset: 0; z-index: 1; pointer-events: none;
  opacity: 0; transition: opacity 0.4s ease;
  background: radial-gradient(
    620px circle at var(--fx-x, 50%) var(--fx-y, 50%),
    rgba(14, 165, 233, 0.10) 0%,
    rgba(14, 165, 233, 0.04) 35%,
    transparent 70%
  );
}
.fx-on .fx-spotlight { opacity: 1; }

/* 2. LINHAS DO BLUEPRINT ACENDENDO PERTO DO CURSOR
   Reaproveita a mesma marcação do .blueprint, então as linhas caem
   exatamente sobre as originais — só mais claras e recortadas num círculo
   em volta do cursor. */
.blueprint-glow > div { border-right-color: rgba(14, 165, 233, 0.5); }
.blueprint-glow {
  opacity: 0; transition: opacity 0.4s ease;
  -webkit-mask-image: radial-gradient(300px circle at var(--fx-x, 50%) var(--fx-y, 50%), #000 10%, transparent 70%);
  mask-image: radial-gradient(300px circle at var(--fx-x, 50%) var(--fx-y, 50%), #000 10%, transparent 70%);
}
.fx-on .blueprint-glow { opacity: 1; }

.blueprint {
  position: fixed; inset: 0; pointer-events: none; z-index: 1;
  max-width: 1400px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(4, 1fr);
}
.blueprint > div { border-right: 1px solid rgba(255,255,255,0.05); height: 100%; }
.blueprint > div:last-child { border-right: none; }

section { padding: 90px 40px; position: relative; z-index: 2; max-width: 1360px; margin: 0 auto; }
.demo-heading { font-weight: 600; font-size: clamp(26px, 3.5vw, 40px); letter-spacing: -0.03em; margin-bottom: 16px; }
.demo-texto { color: var(--text-muted); line-height: 1.6; max-width: 520px; margin: 0; }

js:
// Ponteiro grosso (dedo) não tem posição de repouso: um efeito que segue o
// cursor fica preso onde a pessoa tocou. Quem pediu menos movimento fica de
// fora também.
const FINO = window.matchMedia('(pointer: fine)');
const CALMO = window.matchMedia('(prefers-reduced-motion: reduce)');

export function initSpotlight() {
  if (CALMO.matches || !FINO.matches) return;

  const raiz = document.documentElement;
  raiz.classList.add('fx-on');

  let mx = 0, my = 0, pendente = false;

  // Toda a escrita acontece dentro de um rAF, então um movimento de mouse
  // nunca dispara mais de um layout por quadro.
  function pintar() {
    pendente = false;
    raiz.style.setProperty('--fx-x', mx + 'px');
    raiz.style.setProperty('--fx-y', my + 'px');
  }

  window.addEventListener('mousemove', function (e) {
    mx = e.clientX;
    my = e.clientY;
    if (!pendente) {
      pendente = true;
      requestAnimationFrame(pintar);
    }
  }, { passive: true });
}
